pthread_mutexattr_t attr;
int ret;

// Initialize attribute object
pthread_mutexattr_init(&attr);

// Set Shared Scope: Allows mutex to be placed in shared memory
// and used across different processes.
ret = pthread_mutexattr_setpshared(
    &attr, PTHREAD_PROCESS_SHARED
);

// PTHREAD_PROCESS_PRIVATE (Default): Restricts use to threads
// within the initializing process (Faster).
// ret = pthread_mutexattr_setpshared(
//     &attr, PTHREAD_PROCESS_PRIVATE
// );

// Error check (ret == 0 on success)

pthread_mutexattr_destroy(&attr);
